/**
 * Slack notifications for task state transitions.
 *
 * Covers three events:
 *   in_review — executor finished, PR opened and ready for review
 *   blocked   — executor stuck, human attention needed
 *   done      — reviewer approved, task auto-marked done
 *
 * Reads SLACK_WEBHOOK_URL from process.env. No-ops gracefully when unset.
 * Throws on network/HTTP errors so callers can emit failure events.
 */

export type TaskSlackEvent = "in_review" | "blocked" | "done";

export interface PostTaskSlackOpts {
  event: TaskSlackEvent;
  featureId: string;
  taskId: string;
  taskTitle?: string;
  prUrl?: string;
  /** Only used for "blocked" event. */
  blockedReason?: string;
  webhookUrl: string;
}

const HEADER_TEXT: Record<TaskSlackEvent, (title: string) => string> = {
  in_review: (t) => `👀 Task ready for review: ${t}`,
  blocked:   (t) => `🔴 Task blocked: ${t}`,
  done:      (t) => `✅ Task completed: ${t}`,
};

const FALLBACK_TEXT: Record<TaskSlackEvent, (id: string) => string> = {
  in_review: (id) => `[Task] ${id} is ready for review`,
  blocked:   (id) => `[Task] ${id} is blocked`,
  done:      (id) => `[Task] ${id} is done`,
};

function buildPayload(opts: PostTaskSlackOpts): Record<string, unknown> {
  const { event, featureId, taskId, taskTitle, prUrl, blockedReason } = opts;
  const displayTitle = taskTitle ? `${taskId} — ${taskTitle}` : taskId;
  const prLink = prUrl ? `<${prUrl}|View PR>` : "_not available_";

  const blocks: Record<string, unknown>[] = [
    {
      type: "header",
      text: { type: "plain_text", text: HEADER_TEXT[event](displayTitle) },
    },
    {
      type: "section",
      fields: [
        { type: "mrkdwn", text: `*Feature:*\n${featureId}` },
        { type: "mrkdwn", text: `*Task:*\n${displayTitle}` },
        { type: "mrkdwn", text: `*PR:*\n${prLink}` },
      ],
    },
  ];

  if (event === "blocked" && blockedReason) {
    blocks.push({
      type: "section",
      text: { type: "mrkdwn", text: `*Blocked reason:*\n${blockedReason}` },
    });
  }

  return { text: FALLBACK_TEXT[event](taskId), blocks };
}

export async function postTaskSlack(opts: PostTaskSlackOpts): Promise<void> {
  const payload = buildPayload(opts);
  const resp = await fetch(opts.webhookUrl, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload),
  });
  if (!resp.ok) {
    throw new Error(`Slack webhook returned ${resp.status}: ${await resp.text()}`);
  }
}

