import { readFileSync } from "node:fs";
import { parse as parseYaml } from "yaml";
import { workspaceYamlPath } from "../paths.js";
import { parseGitHubCoords } from "../claim/open-workspace-pr.js";
import type { ModelPolicy } from "./resolve-model-policy.js";

type RepoEntry = { id: string; github: string; local_path?: string; base_branch?: string };

function readWorkspaceRepos(workspaceRoot: string): RepoEntry[] {
  const yaml = parseYaml(
    readFileSync(workspaceYamlPath(workspaceRoot), "utf-8"),
  ) as { repos: RepoEntry[] };
  return yaml.repos;
}

function findRepo(workspaceRoot: string, repoId: string): RepoEntry {
  const repos = readWorkspaceRepos(workspaceRoot);
  const repo = repos.find((r) => r.id === repoId);
  if (!repo) throw new Error(`Repo "${repoId}" not found in workspace.yaml`);
  return repo;
}

export function resolveRepoLocalPath(workspaceRoot: string, repoId: string): string {
  const repo = findRepo(workspaceRoot, repoId);
  if (!repo.local_path?.startsWith("env:")) {
    throw new Error(`Repo "${repoId}" has no "local_path: env:<VAR>" declaration.`);
  }
  const envVar = repo.local_path.slice(4);
  const val = process.env[envVar];
  if (!val) throw new Error(`Env var ${envVar} is not set for repo "${repoId}".`);
  return val;
}

export function resolveRepoBaseBranch(workspaceRoot: string, repoId: string): string {
  const repo = findRepo(workspaceRoot, repoId);
  return repo.base_branch ?? "main";
}

