/**
 * Status icon mapping for Slack notification messages.
 *
 * Maps task/feature status strings to Slack emoji codes per the product spec.
 */

/** Return the Slack emoji code for a given status string. */
export function getStatusIcon(status: string): string {
  const s = status.toLowerCase();

  if (s === "done" || s === "completed" || s === "cancelled") {
    return ":white_check_mark:";
  }
  if (s === "blocked") {
    return ":warning:";
  }
  if (s === "in_handoff" || s === "handoff") {
    return ":handshake:";
  }
  if (
    s === "in_review" ||
    s === "review_incomplete" ||
    s === "change_requested"
  ) {
    return ":mag:";
  }
  if (
    s === "ready" ||
    s === "in_progress" ||
    s === "active" ||
    s === "ready_for_implementation" ||
    s === "in_implementation" ||
    s === "in_design" ||
    s === "in_tdd"
  ) {
    return ":large_green_circle:";
  }

  return ":grey_question:";
}

/** Format a status line: "Status: <icon> <status>" */
export function formatStatusLine(status: string): string {
  return `Status: ${getStatusIcon(status)} ${status}`;
}

