/**
 * Feature message formatters for Slack thread notifications.
 *
 * Pure functions — no I/O, no Slack or Redis imports.
 * Used for both chat.postMessage (create) and chat.update (in-place update).
 */

import type { FeatureContext, FeatureChangedFields, FeatureTrigger } from "./notification.types.js";
import { formatStatusLine } from "./status-icon.js";

/**
 * Format the top-level feature message text.
 *
 * Used for:
 * - `feature_start`: creates the top-level feature message
 * - All subsequent triggers: updates the top-level message in place via chat.update
 *
 * Absent or irrelevant fields are omitted — no blank lines.
 */
export function formatFeatureTopLevel(context: FeatureContext): string {
  const lines: string[] = [];

  lines.push(`Feature: ${context.title}`);
  lines.push(formatStatusLine(context.status));

  if (context.nextAction) {
    lines.push(`Next action: ${context.nextAction}`);
  }
  if (context.blockedReason) {
    lines.push(`Blocked: ${context.blockedReason}`);
  }
  if (context.handoff) {
    lines.push(`Handoff: ${context.handoff}`);
  }
  if (context.featurePr) {
    lines.push(`PR: ${context.featurePr}`);
  }

  lines.push(`Tasks: ${context.totalTaskCount} total`);

  return lines.join("\n");
}

/**
 * Format a feature thread reply message.
 *
 * Contains only the fields that changed for this event, prefixed with the
 * event type. Provides the audit trail alongside the always-current top-level.
 *
 * Absent changed fields are omitted.
 */
export function formatFeatureReply(
  trigger: FeatureTrigger,
  changed: FeatureChangedFields,
): string {
  const lines: string[] = [];

  lines.push(`Type: ${trigger}`);

  if (changed.status !== undefined) {
    lines.push(formatStatusLine(changed.status));
  }
  if (changed.handoff !== undefined && changed.handoff !== null) {
    lines.push(`Handoff: ${changed.handoff}`);
  }
  if (changed.featurePr !== undefined && changed.featurePr !== null) {
    lines.push(`PR: ${changed.featurePr}`);
  }
  if (changed.blockedReason !== undefined && changed.blockedReason !== null) {
    lines.push(`Blocked reason: ${changed.blockedReason}`);
  }
  if (changed.lastUpdatedAt !== undefined && changed.lastUpdatedAt !== null) {
    lines.push(`Updated at: ${changed.lastUpdatedAt}`);
  }

  return lines.join("\n");
}

/**
 * Extract changed feature fields by diffing the current context against a
 * previous snapshot.  Only fields that differ are included in the result.
 */
export function extractFeatureChangedFields(
  previous: Partial<FeatureContext>,
  current: FeatureContext,
): FeatureChangedFields {
  const changed: FeatureChangedFields = {};

  if (previous.status !== current.status) {
    changed.status = current.status;
  }
  if (previous.blockedReason !== current.blockedReason) {
    changed.blockedReason = current.blockedReason ?? null;
  }
  if (previous.handoff !== current.handoff) {
    changed.handoff = current.handoff ?? null;
  }
  if (previous.featurePr !== current.featurePr) {
    changed.featurePr = current.featurePr ?? null;
  }
  if (previous.lastUpdatedAt !== current.lastUpdatedAt) {
    changed.lastUpdatedAt = current.lastUpdatedAt ?? null;
  }

  return changed;
}

