import { describe, it, expect } from "vitest";
import {
  formatFeatureTopLevel,
  formatFeatureReply,
  extractFeatureChangedFields,
} from "../../src/notifications/feature-formatter.js";
import type { FeatureContext, FeatureChangedFields } from "../../src/notifications/notification.types.js";

const BASE_CONTEXT: FeatureContext = {
  title: "Slack Thread Notifications",
  status: "in_implementation",
  totalTaskCount: 8,
};

describe("formatFeatureTopLevel — feature_start", () => {
  it("renders required fields for active feature", () => {
    const text = formatFeatureTopLevel({
      ...BASE_CONTEXT,
      nextAction: "Waiting for T1 to complete",
    });
    expect(text).toContain("Feature: Slack Thread Notifications");
    expect(text).toContain("Status: :large_green_circle: in_implementation");
    expect(text).toContain("Next action: Waiting for T1 to complete");
    expect(text).toContain("Tasks: 8 total");
  });

  it("omits next_action when absent", () => {
    const text = formatFeatureTopLevel(BASE_CONTEXT);
    expect(text).not.toContain("Next action");
  });

  it("omits blocked reason when absent", () => {
    const text = formatFeatureTopLevel(BASE_CONTEXT);
    expect(text).not.toContain("Blocked");
  });

  it("omits handoff when absent", () => {
    const text = formatFeatureTopLevel(BASE_CONTEXT);
    expect(text).not.toContain("Handoff");
  });

  it("omits feature PR when absent", () => {
    const text = formatFeatureTopLevel(BASE_CONTEXT);
    expect(text).not.toContain("PR:");
  });
});

describe("formatFeatureTopLevel — full current state snapshot", () => {
  it("renders blocked reason when feature is blocked", () => {
    const text = formatFeatureTopLevel({
      ...BASE_CONTEXT,
      status: "blocked",
      blockedReason: "Missing SLACK_BOT_TOKEN",
    });
    expect(text).toContain("Status: :warning: blocked");
    expect(text).toContain("Blocked: Missing SLACK_BOT_TOKEN");
  });

  it("renders handoff when in_handoff", () => {
    const text = formatFeatureTopLevel({
      ...BASE_CONTEXT,
      status: "in_handoff",
      handoff: "docs/features/feature-1/handoffs/handoff.md",
    });
    expect(text).toContain("Status: :handshake: in_handoff");
    expect(text).toContain("Handoff: docs/features/feature-1/handoffs/handoff.md");
  });

  it("renders feature PR when set", () => {
    const text = formatFeatureTopLevel({
      ...BASE_CONTEXT,
      featurePr: "https://github.com/org/repo/pull/42",
    });
    expect(text).toContain("PR: https://github.com/org/repo/pull/42");
  });

  it("renders done status with correct icon", () => {
    const text = formatFeatureTopLevel({
      ...BASE_CONTEXT,
      status: "done",
      featurePr: "https://github.com/org/repo/pull/42",
    });
    expect(text).toContain("Status: :white_check_mark: done");
  });

  it("omits nextAction when null", () => {
    const text = formatFeatureTopLevel({ ...BASE_CONTEXT, nextAction: null });
    expect(text).not.toContain("Next action");
  });

  it("omits blockedReason when null", () => {
    const text = formatFeatureTopLevel({ ...BASE_CONTEXT, blockedReason: null });
    expect(text).not.toContain("Blocked");
  });

  it("omits handoff when null", () => {
    const text = formatFeatureTopLevel({ ...BASE_CONTEXT, handoff: null });
    expect(text).not.toContain("Handoff");
  });

  it("omits featurePr when null", () => {
    const text = formatFeatureTopLevel({ ...BASE_CONTEXT, featurePr: null });
    expect(text).not.toContain("PR:");
  });
});

describe("formatFeatureReply — changed fields only", () => {
  it("renders type and status when status changed", () => {
    const changed: FeatureChangedFields = { status: "done" };
    const text = formatFeatureReply("feature_completed", changed);
    expect(text).toContain("Type: feature_completed");
    expect(text).toContain("Status: :white_check_mark: done");
  });

  it("renders only Type when no fields changed", () => {
    const text = formatFeatureReply("feature_summary_changed", {});
    expect(text).toBe("Type: feature_summary_changed");
  });

  it("renders handoff when changed", () => {
    const changed: FeatureChangedFields = {
      handoff: "docs/features/feature-1/handoffs/handoff.md",
    };
    const text = formatFeatureReply("handoff_submitted", changed);
    expect(text).toContain("Type: handoff_submitted");
    expect(text).toContain("Handoff: docs/features/feature-1/handoffs/handoff.md");
  });

  it("renders feature PR when changed", () => {
    const changed: FeatureChangedFields = {
      featurePr: "https://github.com/org/repo/pull/99",
    };
    const text = formatFeatureReply("handoff_submitted", changed);
    expect(text).toContain("PR: https://github.com/org/repo/pull/99");
  });

  it("renders blocked reason when changed", () => {
    const changed: FeatureChangedFields = {
      status: "blocked",
      blockedReason: "operator_cancelled",
    };
    const text = formatFeatureReply("feature_summary_changed", changed);
    expect(text).toContain("Blocked reason: operator_cancelled");
  });

  it("renders lastUpdatedAt when changed", () => {
    const changed: FeatureChangedFields = {
      lastUpdatedAt: "2026-05-20T10:00:00+0000",
    };
    const text = formatFeatureReply("feature_summary_changed", changed);
    expect(text).toContain("Updated at: 2026-05-20T10:00:00+0000");
  });

  it("omits null fields", () => {
    const changed: FeatureChangedFields = {
      status: "done",
      handoff: null,
      featurePr: null,
      blockedReason: null,
    };
    const text = formatFeatureReply("feature_completed", changed);
    expect(text).not.toContain("Handoff:");
    expect(text).not.toContain("PR:");
    expect(text).not.toContain("Blocked reason:");
  });
});

describe("extractFeatureChangedFields", () => {
  it("returns empty when nothing changed", () => {
    const ctx: FeatureContext = { ...BASE_CONTEXT };
    const changed = extractFeatureChangedFields(ctx, ctx);
    expect(Object.keys(changed)).toHaveLength(0);
  });

  it("captures status change", () => {
    const prev: Partial<FeatureContext> = { status: "in_implementation" };
    const curr: FeatureContext = { ...BASE_CONTEXT, status: "done" };
    const changed = extractFeatureChangedFields(prev, curr);
    expect(changed.status).toBe("done");
  });

  it("captures blockedReason change", () => {
    const prev: Partial<FeatureContext> = { blockedReason: null };
    const curr: FeatureContext = { ...BASE_CONTEXT, blockedReason: "some_reason" };
    const changed = extractFeatureChangedFields(prev, curr);
    expect(changed.blockedReason).toBe("some_reason");
  });

  it("captures featurePr change", () => {
    const prev: Partial<FeatureContext> = { featurePr: null };
    const curr: FeatureContext = { ...BASE_CONTEXT, featurePr: "https://github.com/org/repo/pull/1" };
    const changed = extractFeatureChangedFields(prev, curr);
    expect(changed.featurePr).toBe("https://github.com/org/repo/pull/1");
  });

  it("captures handoff change", () => {
    const prev: Partial<FeatureContext> = { handoff: null };
    const curr: FeatureContext = { ...BASE_CONTEXT, handoff: "path/to/handoff.md" };
    const changed = extractFeatureChangedFields(prev, curr);
    expect(changed.handoff).toBe("path/to/handoff.md");
  });

  it("captures lastUpdatedAt change", () => {
    const prev: Partial<FeatureContext> = { lastUpdatedAt: "2026-01-01T00:00:00Z" };
    const curr: FeatureContext = { ...BASE_CONTEXT, lastUpdatedAt: "2026-05-20T10:00:00Z" };
    const changed = extractFeatureChangedFields(prev, curr);
    expect(changed.lastUpdatedAt).toBe("2026-05-20T10:00:00Z");
  });

  it("does not include unchanged fields", () => {
    const prev: Partial<FeatureContext> = {
      status: "in_implementation",
      blockedReason: null,
    };
    const curr: FeatureContext = {
      ...BASE_CONTEXT,
      status: "in_implementation",
      blockedReason: null,
    };
    const changed = extractFeatureChangedFields(prev, curr);
    expect(changed.status).toBeUndefined();
    expect(changed.blockedReason).toBeUndefined();
  });
});

